import{_ as o}from"./chunks/accueil.BjCD5sJc.js";import{_ as s,o as t,c as a,a2 as u}from"./chunks/framework.Zh78JZbW.js";const n="/kodus-releases/screenshots/actu.png",r="/kodus-releases/screenshots/actu-sondage.png",v=JSON.parse('{"title":"Actu & Commu","description":"","frontmatter":{},"headers":[],"relativePath":"guide/actu.md","filePath":"guide/actu.md"}'),i={name:"guide/actu.md"};function l(c,e,p,m,d,g){return t(),a("div",null,[...e[0]||(e[0]=[u('<h1 id="actu-commu" tabindex="-1">Actu &amp; Commu <a class="header-anchor" href="#actu-commu" aria-label="Permalink to &quot;Actu &amp; Commu&quot;">​</a></h1><p><strong>Actu &amp; Commu</strong> rassemble les annonces de Kodus et du Goupil SMP, les sondages, les questionnaires et les créations de la communauté publiées sur Modrinth.</p><h2 id="sur-l-accueil" tabindex="-1">Sur l&#39;accueil <a class="header-anchor" href="#sur-l-accueil" aria-label="Permalink to &quot;Sur l&#39;accueil&quot;">​</a></h2><p>Les nouvelles publications défilent sous le bouton <strong>Jouer</strong> : faites-les glisser, ou utilisez les flèches. Une publication quitte ce bandeau une fois vue, sauf les plus importantes, que l&#39;équipe Kodus y laisse en permanence ; toutes restent dans la page Actu &amp; Commu. <strong>Tout voir</strong> ouvre la page complète. Le bouton en haut de l&#39;accueil (l&#39;icône de journal) affiche le nombre de nouveautés.</p><p><img src="'+o+'" alt="Accueil de Kodus : bandeau Actu &amp; Commu sous le bouton Jouer"></p><h2 id="la-page-actu-commu" tabindex="-1">La page Actu &amp; Commu <a class="header-anchor" href="#la-page-actu-commu" aria-label="Permalink to &quot;La page Actu &amp; Commu&quot;">​</a></h2><p><img src="'+n+'" alt="Page Actu &amp; Commu : annonce épinglée, sondage, questionnaire et projet de la communauté"></p><p>Les filtres en haut de la page affichent :</p><ul><li><strong>Annonces</strong> : nouveautés de Kodus, événements du Goupil SMP…</li><li><strong>Communauté</strong> : mods, packs et shaders créés par des joueurs Kodus. Ils portent le badge <strong>Communauté Kodus</strong>, aussi dans la recherche de mods ;</li><li><strong>Sondages</strong> : sondages et questionnaires.</li></ul><p>Cliquez sur une publication pour l&#39;ouvrir en grand. Un projet de la communauté ouvre directement sa fiche, d&#39;où vous pouvez l&#39;installer ou jouer avec.</p><h2 id="sondages-et-questionnaires" tabindex="-1">Sondages et questionnaires <a class="header-anchor" href="#sondages-et-questionnaires" aria-label="Permalink to &quot;Sondages et questionnaires&quot;">​</a></h2><p>Choisissez votre réponse, puis cliquez sur <strong>Voter</strong>. Selon le sondage, les résultats s&#39;affichent tout de suite après votre vote ou seulement à sa fin. Vous pouvez changer votre vote tant que le sondage est ouvert.</p><p><img src="'+r+'" alt="Résultats d&#39;un sondage après avoir voté"></p><p>Les questionnaires se remplissent de la même façon. Les réponses marquées d&#39;une étoile (*) sont obligatoires.</p><div class="info custom-block"><p class="custom-block-title">Un vote par joueur</p><p>Votes et réponses sont liés à votre compte Kodus : un seul par pseudo, quel que soit le nombre d&#39;ordinateurs.</p></div><h2 id="proposer-votre-projet" tabindex="-1">Proposer votre projet <a class="header-anchor" href="#proposer-votre-projet" aria-label="Permalink to &quot;Proposer votre projet&quot;">​</a></h2><p>Vous avez publié un mod, un pack de ressources, un shader ou un modpack sur Modrinth ? Sur la page <strong>Actu &amp; Commu</strong>, cliquez sur <strong>Proposer mon projet</strong>, collez son lien et ajoutez un message si vous le souhaitez. L&#39;équipe Kodus reçoit la demande et peut le mettre en avant. La fenêtre indique ensuite si votre proposition est en attente, acceptée ou refusée.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>Dans <strong>Paramètres</strong> → onglet <strong>Notifications</strong> → <strong>Actu &amp; Commu</strong>, choisissez les publications pour lesquelles vous êtes prévenu : annonces, nouveaux projets de la communauté, sondages et questionnaires. Le nombre de nouveautés reste toujours affiché sur le bouton Actu &amp; Commu.</p>',19)])])}const q=s(i,[["render",l]]);export{v as __pageData,q as default};
